# bash completion for __CLYOPS_PROG__ (generated by clyops)
# Enable with:  eval "$(__CLYOPS_PROG__ --completion bash)"
_clyops___CLYOPS_FUNC__() {
    local cur prev="" data rec name short type kind values rest i skip=0 cword=0 w line="$COMP_LINE" trimmed
    local -A otype=() okind=() ovalues=()
    local -a names=() cmds=() akind=() avalues=() aarity=() cw=()
    # Readline also splits words at the other COMP_WORDBREAKS characters, so "zone:eu" arrives
    # as "zone" ":" "eu". Join the pieces no whitespace separates (keeping COMP_WORDS' quoting),
    # except around "=", which --opt=VALUE handling below expects on its own.
    for (( i = 0; i <= COMP_CWORD && i < ${#COMP_WORDS[@]}; i++ )); do
        w="${COMP_WORDS[i]}"
        trimmed="${line#"${line%%[![:space:]]*}"}"
        if (( i > 0 )) && [[ "$trimmed" == "$line" && "$w" != =* && "${cw[-1]}" != *= ]]; then
            cw[-1]+="$w"
        else
            cw+=("$w")
        fi
        line="${trimmed:${#w}}"
        (( i == COMP_CWORD )) && cword=$(( ${#cw[@]} - 1 ))
    done
    (( COMP_CWORD >= ${#COMP_WORDS[@]} )) && { cw+=(""); cword=$(( ${#cw[@]} - 1 )); }
    cur="${cw[cword]}"
    (( cword > 0 )) && prev="${cw[cword-1]}"
    # The words before the cursor let a dispatcher answer for the subcommand being typed.
    data=$("${COMP_WORDS[0]}" --bash-completion -- "${cw[@]:1:cword-1}" 2>/dev/null) || return 0
    [[ "$data" == "#clyops-completion 1"* ]] || return 0

    while IFS=$'\t' read -r rec name short type kind values rest; do
        [[ "$values" == - ]] && values=""
        case "$rec" in
            skip) skip="$name" ;;
            cmd) cmds+=("$name") ;;
            opt)
                for i in "$name" "$short"; do
                    [[ -z "$i" || "$i" == - ]] && continue
                    names+=("$i"); otype[$i]="$type"; okind[$i]="$kind"; ovalues[$i]="$values"
                done ;;
            arg)
                # arg records: name, arity, kind, values, description
                [[ "$kind" == - ]] && kind=""
                aarity+=("$short"); akind+=("$type"); avalues+=("$kind") ;;
        esac
    done <<< "$data"
    # Words up to and including a dispatched subcommand belong to the dispatcher.
    local first=$(( 1 + skip ))
    (( cword <= first )) && prev=""

    # Option value: --opt=VALUE (bash splits on "=") or --opt VALUE.
    local opt=""
    if [[ "$cur" == --*=* ]]; then opt="${cur%%=*}"; cur="${cur#*=}"
    elif [[ "$cur" == = && "${otype[$prev]}" == value ]]; then opt="$prev"; cur=""
    elif [[ "$prev" == = ]] && (( cword > first + 1 )); then opt="${cw[cword-2]}"
    elif [[ "$prev" == -* && "${otype[$prev]}" == value ]]; then opt="$prev"
    fi
    if [[ -n "$opt" ]]; then
        _clyops_value___CLYOPS_FUNC__ "${okind[$opt]}" "${ovalues[$opt]}" "$cur"
        _clyops_trim___CLYOPS_FUNC__ "$cur"
        return 0
    fi

    if [[ "$cur" == -* ]]; then
        COMPREPLY=($(compgen -W "${names[*]}" -- "$cur"))
        return 0
    fi

    # A dispatcher group: complete its subcommands.
    if (( ${#cmds[@]} )); then
        COMPREPLY=($(compgen -W "${cmds[*]}" -- "$cur"))
        return 0
    fi

    # A dispatched program without completion data: fall back to file names.
    if (( skip > 0 && ${#names[@]} == 0 && ${#akind[@]} == 0 )); then
        compopt -o default 2>/dev/null
        COMPREPLY=()
        return 0
    fi

    # Positional: count earlier positionals, skipping options and their values.
    local pos=0 endopts="" w
    for (( i = first; i < cword; i++ )); do
        w="${cw[i]}"
        if [[ -z "$endopts" && "$w" == -- ]]; then endopts=1
        elif [[ -z "$endopts" && "$w" == -?* ]]; then
            [[ "$w" != *=* && "${otype[$w]}" == value ]] && (( i++ ))
        elif [[ "$w" != = ]]; then (( pos++ ))
        fi
    done
    local n=${#akind[@]}
    (( n == 0 )) && return 0
    if (( pos >= n )); then
        [[ "${aarity[n-1]}" == variadic ]] || return 0
        pos=$(( n - 1 ))
    fi
    _clyops_value___CLYOPS_FUNC__ "${akind[pos]}" "${avalues[pos]}" "$cur"
    _clyops_trim___CLYOPS_FUNC__ "$cur"
}

# Readline replaces only the text after the last word break in the word (a ":"
# or "@" in COMP_WORDBREAKS): drop what comes before it from each completion.
_clyops_trim___CLYOPS_FUNC__() {
    local k c strip=""
    for (( k = ${#1} - 1; k >= 0; k-- )); do
        c="${1:k:1}"
        [[ "$c" != [[:space:]=\"\'] && "$COMP_WORDBREAKS" == *"$c"* ]] && { strip="${1:0:k+1}"; break; }
    done
    [[ -n "$strip" ]] || return 0
    for k in "${!COMPREPLY[@]}"; do COMPREPLY[k]="${COMPREPLY[k]#"$strip"}"; done
}

_clyops_value___CLYOPS_FUNC__() {
    local kind="$1" values="$2" cur="$3" dir IFS=$'\n'
    case "$kind" in
        choice) COMPREPLY=($(IFS=$' \t\n'; compgen -W "${values//,/ }" -- "$cur")) ;;
        file|dir)
            local flag=-f
            [[ "$kind" == dir ]] && flag=-d
            compopt -o filenames 2>/dev/null
            COMPREPLY=($(compgen $flag -- "$cur"))
            # Bare names also match entries in the option's search dirs.
            if [[ -n "$values" && "$cur" != /* && "$cur" != ./* && "$cur" != ../* ]]; then
                local -a dirs
                IFS=: read -ra dirs <<< "$values"
                for dir in "${dirs[@]}"; do
                    [[ -d "$dir" ]] && COMPREPLY+=($(cd "$dir" && compgen $flag -- "$cur"))
                done
            fi ;;
        command)
            # A program on PATH, or a path once the word has a slash.
            if [[ "$cur" == */* ]]; then
                compopt -o filenames 2>/dev/null
                COMPREPLY=($(compgen -f -- "$cur"))
            else
                COMPREPLY=($(compgen -c -- "$cur"))
            fi ;;
        host) COMPREPLY=($(compgen -A hostname -- "$cur")) ;;
        none) COMPREPLY=() ;;
        *) compopt -o default 2>/dev/null; COMPREPLY=() ;;
    esac
}

complete -F _clyops___CLYOPS_FUNC__ __CLYOPS_PROG__
